// _chr is a player ID (e.g. "para_cp0008"), _avt a Fighting Spirit ID
// (e.g. "ck0001"). The slot is enabled and unlocked for the change,
// then its previous lock state is restored.
local hdl = CMND_GET_PARTY_HANDLE(_chr);
local lock = CMND_GET_AVATAR_LOCK_FLAG(hdl);
CMND_SET_AVATAR_ENABLE(hdl, true);
CMND_SET_AVATAR_LOCK_FLAG(hdl, false);
CMND_ATTACH_AVATAR(_chr, _avt);
CMND_SET_AVATAR_LOCK_FLAG(hdl, lock);

// Story event giving a Fighting Spirit to the protagonist, with the
// jingle and "obtained" message handled by the wrapper.
RunAttachAvatar("para_cp0008", "ck0001");

// Overwrite the current Fighting Spirit: the old one is not returned to
// the inventory and its experience is not saved.
CMND_ATTACH_AVATAR("para_cp0008", "ck0033", 0);
